package com.yeyamo_mobile.api.culture_service.interfaces.rest;
import static com.yeyamo_mobile.api.culture_service.application.CultureDtos.*;import com.yeyamo_mobile.api.culture_service.application.CultureContentService;import jakarta.validation.Valid;import java.security.Principal;import java.util.UUID;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/culture") @PreAuthorize("hasAnyRole('EDITOR','MODERATOR','ADMIN','SUPER_ADMIN')") public class AdminCultureController{private final CultureContentService service;public AdminCultureController(CultureContentService s){service=s;}@GetMapping("/contents")public Page<ContentResponse> list(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.adminList(p);}@GetMapping("/contents/{id}")public ContentResponse get(@PathVariable UUID id){return service.adminGet(id);}@PostMapping("/contents")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAnyRole('EDITOR','ADMIN','SUPER_ADMIN')")public ContentResponse create(@RequestBody@Valid ContentRequest r,Principal p){return service.create(r,p.getName(),true);}@PutMapping("/contents/{id}")@PreAuthorize("hasAnyRole('EDITOR','ADMIN','SUPER_ADMIN')")public ContentResponse update(@PathVariable UUID id,@RequestBody@Valid ContentRequest r,Principal p){return service.update(id,r,p.getName(),true);}@PatchMapping("/contents/{id}/status")@PreAuthorize("hasAnyRole('MODERATOR','ADMIN','SUPER_ADMIN')")public ContentResponse status(@PathVariable UUID id,@RequestBody@Valid StatusRequest r){return service.status(id,r);}@GetMapping("/contributions")public Page<ContentResponse> contributions(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return service.adminContributions(p);}@PostMapping("/contributions/{id}/review")@PreAuthorize("hasAnyRole('MODERATOR','ADMIN','SUPER_ADMIN')")public ContentResponse review(@PathVariable UUID id,@RequestBody@Valid ReviewRequest r,Principal p){return service.review(id,r,p.getName());}@PatchMapping("/translations/{id}/verify")@PreAuthorize("hasAnyRole('MODERATOR','ADMIN','SUPER_ADMIN')")public TranslationResponse verifyTranslation(@PathVariable UUID id,Principal p){return service.verifyTranslation(id,p.getName());}}
